<?php
declare(strict_types=1);namespace App\Modules\SupplierInvoices\Services;
use App\Core\Auth\Auth;use App\Core\Database\Database;use App\Core\Exceptions\BusinessRuleException;use App\Modules\SupplierInvoices\DTOs\SupplierInvoiceData;use App\Modules\SupplierInvoices\DTOs\SupplierInvoiceTableQuery;use App\Modules\SupplierInvoices\Repositories\SupplierInvoiceRepository;use App\Shared\Numbering\NumberGeneratorService;
final class SupplierInvoiceService{private const PROJECT_STATUSES=['planning','active','on_hold','completed'];public function __construct(private readonly SupplierInvoiceRepository$r,private readonly NumberGeneratorService$numbers,private readonly Database$db,private readonly Auth$auth){}
public function find(int$id):array{return$this->r->find($id)??throw new BusinessRuleException('فاتورة المورد غير موجودة.');}public function details(int$id):array{return['invoice'=>$this->find($id),'lines'=>$this->r->lines($id),'displayTotal'=>$this->r->total($id)];}
public function save(SupplierInvoiceData$d,?int$id=null):int{return$this->db->transaction(function()use($d,$id){$old=$id===null?null:$this->r->find($id,true);if($id!==null&&$old===null)throw new BusinessRuleException('فاتورة المورد غير موجودة.');if($old!==null&&$old['status']!=='draft')throw new BusinessRuleException('يمكن تعديل مسودة الفاتورة فقط.');if($old!==null&&$this->year((string)$old['invoice_code'])!==substr($d->invoiceDate,0,4))throw new BusinessRuleException('لا يمكن تغيير سنة تاريخ الفاتورة. ألغِ المسودة وأنشئ فاتورة جديدة.');$this->validateMasters($d,false);if($this->r->numberExists($d->vendorId,$d->invoiceNumber,$id))throw new BusinessRuleException('رقم الفاتورة مستخدم بالفعل لهذا المورد.');if($id===null)$id=$this->r->create($this->numbers->nextSupplierInvoiceCode((int)substr($d->invoiceDate,0,4)),$d,$this->user());else$this->r->update($id,$d);$this->r->syncLines($id,$d->lines);return$id;});}
public function approve(int$id):void{$probe=$this->find($id);$this->db->transaction(function()use($id,$probe){$project=$this->r->project((int)$probe['project_id'],true)??throw new BusinessRuleException('المشروع غير موجود.');$invoice=$this->r->find($id,true)??throw new BusinessRuleException('فاتورة المورد غير موجودة.');if($invoice['status']!=='draft')throw new BusinessRuleException('يمكن اعتماد مسودة الفاتورة فقط.');$vendor=$this->r->vendor((int)$invoice['vendor_id'],true)??throw new BusinessRuleException('المورد غير موجود.');$lines=$this->r->lines($id,true);if($lines===[])throw new BusinessRuleException('لا يمكن اعتماد فاتورة بلا بنود.');if(!(bool)$vendor['is_active']||!in_array($vendor['vendor_type'],['supplier','both'],true))throw new BusinessRuleException('المورد غير نشط أو غير مصنف كمورد.');if(!in_array($project['status'],self::PROJECT_STATUSES,true))throw new BusinessRuleException('حالة المشروع لا تسمح باعتماد فاتورة مورد.');$ids=array_values(array_unique(array_map('intval',array_column($lines,'cost_code_id'))));sort($ids);$masters=$this->r->costCodes($ids,true);$byId=array_column($masters,null,'id');if(count($byId)!==count($ids))throw new BusinessRuleException('أحد أكواد التكلفة غير موجود.');foreach($lines as$line){$master=$byId[$line['cost_code_id']]??null;if($master===null||!(bool)$master['cost_code_active']||!(bool)$master['section_active'])throw new BusinessRuleException('أحد أكواد التكلفة أو أقسام الأعمال غير نشط.');if($this->r->sourceCostExists($id,(int)$line['id']))throw new BusinessRuleException('تم إنشاء تكلفة لأحد بنود الفاتورة مسبقًا.');}$total=$this->r->total($id);if($this->compare($total,'0.00')<=0)throw new BusinessRuleException('إجمالي الفاتورة يجب أن يكون أكبر من صفر.');$user=$this->user();foreach($lines as$line){$master=$byId[$line['cost_code_id']];$this->r->createCost($this->numbers->nextProjectActualCostCode((int)substr((string)$invoice['invoice_date'],0,4)),$invoice,$line,$master,$user);$this->r->freezeLine((int)$line['id'],$master);}$this->r->approve($id,$total,$vendor,$project,$user);$verified=$this->r->find($id,true);if(($verified['status']??null)!=='approved')throw new\RuntimeException('Supplier invoice approval failed.');});}
public function cancel(int$id):void{$probe=$this->find($id);$this->db->transaction(function()use($id,$probe){$this->r->project((int)$probe['project_id'],true);$invoice=$this->r->find($id,true)??throw new BusinessRuleException('فاتورة المورد غير موجودة.');if($invoice['status']!=='draft')throw new BusinessRuleException('يمكن إلغاء مسودة الفاتورة فقط.');$this->r->cancel($id,$this->user());});}
private function validateMasters(SupplierInvoiceData$d,bool$lock):void{$vendor=$this->r->vendor($d->vendorId,$lock);if($vendor===null||!(bool)$vendor['is_active']||!in_array($vendor['vendor_type'],['supplier','both'],true))throw new BusinessRuleException('اختر موردًا نشطًا ومصنفًا كمورد.');$project=$this->r->project($d->projectId,$lock);if($project===null||!in_array($project['status'],self::PROJECT_STATUSES,true))throw new BusinessRuleException('اختر مشروعًا صالحًا غير ملغي.');$ids=array_values(array_unique(array_map('intval',array_column($d->lines,'cost_code_id'))));sort($ids);$codes=$this->r->costCodes($ids,$lock);if(count($codes)!==count($ids))throw new BusinessRuleException('أحد أكواد التكلفة غير موجود.');foreach($codes as$c)if(!(bool)$c['cost_code_active']||!(bool)$c['section_active'])throw new BusinessRuleException('اختر أكواد تكلفة نشطة ضمن أقسام نشطة.');}
private function compare(string$a,string$b):int{$x=$this->db->execute('SELECT CASE WHEN CAST(? AS DECIMAL(18,2))<CAST(? AS DECIMAL(18,2)) THEN -1 WHEN CAST(? AS DECIMAL(18,2))>CAST(? AS DECIMAL(18,2)) THEN 1 ELSE 0 END c',[$a,$b,$a,$b]);return(int)(($x instanceof \mysqli_result?$x->fetch_assoc():[])['c']??0);}private function year(string$code):string{return preg_match('/^SINV-(\d{4})-/',$code,$m)?$m[1]:'';}private function user():int{return$this->auth->id()??throw new BusinessRuleException('تعذر تحديد المستخدم الحالي.');}public function references():array{return$this->r->references();}public function dataTable(SupplierInvoiceTableQuery$q):array{$x=$this->r->dataTable($q);return['draw'=>$q->draw,'recordsTotal'=>$x['recordsTotal'],'recordsFiltered'=>$x['recordsFiltered'],'data'=>$x['rows']];}}
